    strategy.put(
        StrategyRecord(
            goal_id="goal-1",
            score=0.8,
            root_task_id="root-1",
            task_ids=["root-1", "child-1"],
            team_id="team-1",
            lead_id="lead-1",
            task_outcomes={"child-1": "passed"},
            delivery_shape="team",
            staffing_requirements=(StaffingRequirement("engineer"),),
        )
    )
    horizon = Horizon(
        goals=goals,
        intake=FakeIntakePort(),
        outcomes=FakeOutcomeFeed(),
        capacity=_Capacity(),
        strategy=strategy,
        decisions=DecisionStore(tmp_path / "decisions.json"),
    )

    goal = horizon.goal_view("goal-1")

