def test_recover_resubmits_failed_goal_with_diagnostic(tmp_path):
    horizon, intake, feed = _decomposed_horizon(tmp_path)
    goal = horizon.state()[0].goals[0]

    feed.emit(
        OutcomeEvent(
            kind="run.evaluated",
            task_id=goal.task_id,
            goal_id=goal.id,
            passed=False,
            detail="evaluator reply missing <verdict> section",
        )
    )

    recovered = horizon.recover(max_attempts=3)
    assert recovered == [goal.id]
    assert len(intake.submitted) == 2  # original + one recovery
    retry = intake.submitted[-1]
    assert "missing <verdict>" in retry["intent"]
    assert "previous attempt" in retry["intent"].lower()
    assert retry["fingerprint"] != intake.submitted[0]["fingerprint"]  # a fresh task, not a dedup

    assert horizon.recover() == []  # needs_recovery cleared -> no-op


def test_recover_respects_max_attempts(tmp_path):
    horizon, intake, feed = _decomposed_horizon(tmp_path)

    for _ in range(5):
        goal = horizon.state()[0].goals[0]
        feed.emit(
            OutcomeEvent(
                kind="run.evaluated",
                task_id=goal.task_id,
                goal_id=goal.id,
                passed=False,
                detail="nope",
            )
        )
        horizon.recover(max_attempts=2)

    # initial submit (attempt 1) + exactly one recovery (attempt 2) — then capped
    assert len(intake.submitted) == 2


def test_note_outcome_funnels_a_consumer_detected_failure(tmp_path):
    horizon, intake, _ = _decomposed_horizon(tmp_path)
    goal = horizon.state()[0].goals[0]

    # a beat that errored (no bus verdict) — the composition root reports it
    horizon.note_outcome(
        goal.id, passed=False, diagnostic="RunTaskError: evaluator reply missing <verdict>"
    )
    assert horizon.listener_stats()["handled"] == 1

    recovered = horizon.recover()
    assert recovered == [goal.id]
    assert "evaluator reply missing <verdict>" in intake.submitted[-1]["intent"]


def test_sweep_staleness_drifts_and_resurfaces_aged_goals(tmp_path):
    from datetime import UTC, datetime, timedelta

    from horizon.model._strategy import StrategyRecord

    now = datetime(2026, 7, 9, 12, 0, 0, tzinfo=UTC)
    intake = FakeIntakePort()
    strategy = StrategyStore(tmp_path / "strategy.json")
    # a goal verified 2 days ago (on_track + done) with a live task -> should drift
    strategy.put(
        StrategyRecord(
            goal_id="g1",
            title="Old goal",
            score=0.30,
            health="on_track",
            done=True,
            task_id="task_1",
            last_outcome_at=(now - timedelta(days=2)).isoformat(),
        )
    )
    # a goal verified 5 minutes ago -> should NOT drift
    strategy.put(
        StrategyRecord(
            goal_id="g2",
            title="Fresh goal",
            score=0.30,
            health="on_track",
            done=True,
            task_id="task_2",
            last_outcome_at=(now - timedelta(minutes=5)).isoformat(),
        )
    )
    intake.priorities["task_1"] = "low"
    intake.priorities["task_2"] = "low"
    horizon = Horizon(
        goals=FakeGoalStore(),
        intake=intake,
        outcomes=FakeOutcomeFeed(),
        decisions=DecisionStore(tmp_path / "decisions.json"),
        strategy=strategy,
    )

    drifted = horizon.sweep_staleness(now=now)

    assert drifted == ["g1"]
    aged = strategy.get("g1")
    assert aged.health == "drifting"
    assert aged.done is False  # re-opened for re-verification
    assert aged.score == 0.45  # 0.30 + 0.15 stale_bump
    assert intake.priorities["task_1"] == "medium"  # 0.45 crosses the low->medium threshold
    assert strategy.get("g2").health == "on_track"  # fresh goal untouched


def test_recover_new_task_identity_survives_store_round_trip(tmp_path):
    horizon, _intake, feed = _decomposed_horizon(tmp_path)
    goal = horizon.state()[0].goals[0]
    original_task = goal.task_id

    feed.emit(
        OutcomeEvent(
            kind="run.evaluated",
            task_id=original_task,
            goal_id=goal.id,
            passed=False,
            detail="boom",
        )
    )
    recovered = horizon.recover(max_attempts=3)
    assert recovered == [goal.id]

    # A fresh read reconstructs the record from the store — the retry task must survive it.
    refreshed = next(g for g in horizon.state()[0].goals if g.id == goal.id)
    assert refreshed.task_id != original_task

    # And the retry is the goal's new root: its passing outcome completes the goal.
    feed.emit(
        OutcomeEvent(
            kind="run.evaluated",
            task_id=refreshed.task_id,
            goal_id=goal.id,
            passed=True,
        )
    )
    final = next(g for g in horizon.state()[0].goals if g.id == goal.id)
    assert final.health == "on_track"
